use crate::allocator::Allocator;
use crate::ast::{Node, Span};
use smallvec::SmallVec;

use super::super::line_scan::{line_end, line_terminator_end};

/// One contiguous normalized line segment: generated bytes
/// `gen_start..gen_end` came from original bytes `src_start..src_start + (gen_end - gen_start)`.
#[derive(Clone, Copy)]
pub(super) struct MappedLine {
    gen_start: u32,
    gen_end: u32,
    src_start: u32,
}

pub(super) struct JsxChildSource<'a> {
    pub source: &'a str,
    pub offsets: Option<SmallVec<[MappedLine; 8]>>,
}

pub(super) fn normalize_indentation<'a>(
    allocator: &'a Allocator,
    source: &'a str,
) -> JsxChildSource<'a> {
    normalize_indentation_with_protected(allocator, source, &[])
}

pub(super) fn normalize_indentation_with_protected<'a>(
    allocator: &'a Allocator,
    source: &'a str,
    protected: &[(usize, usize)],
) -> JsxChildSource<'a> {
    let common_indent = common_line_indent(source, protected);
    if common_indent == 0 {
        return JsxChildSource {
            source,
            offsets: None,
        };
    }

    let bytes = source.as_bytes();
    let mut normalized = crate::allocator::String::with_capacity_in(source.len(), allocator.bump());
    let mut lines: SmallVec<[MappedLine; 8]> = SmallVec::new();
    let mut line_start = 0usize;
    let mut protected_idx = 0usize;

    while line_start < bytes.len() {
        let (line_end, next_line) = line_bounds(bytes, line_start);
        while protected_idx < protected.len() && protected[protected_idx].1 <= line_start {
            protected_idx += 1;
        }
        let is_protected =
            protected_idx < protected.len() && protected[protected_idx].0 < line_start;
        let content_start = if is_protected {
            line_start
        } else {
            strip_indent_columns(bytes, line_start, line_end, common_indent)
        };
        if content_start < next_line {
            let gen_start = normalized.len() as u32;
            normalized.push_str(&source[content_start..next_line]);
            let gen_end = normalized.len() as u32;
            lines.push(MappedLine {
                gen_start,
                gen_end,
                src_start: content_start as u32,
            });
        }
        line_start = next_line;
    }

    JsxChildSource {
        source: normalized.into_bump_str(),
        offsets: Some(lines),
    }
}

/// JSX normalization maps generated byte boundaries back to its original
/// child source. The shared traversal owns all AST node and attribute shapes.
struct JsxSourceMap<'s> {
    source_offset: u32,
    lines: &'s [MappedLine],
}

impl super::super::spans::SpanMap for JsxSourceMap<'_> {
    fn map_span(&self, span: Span) -> Span {
        Span::new(
            self.source_offset + boundary_offset(span.start, self.lines),
            self.source_offset + boundary_offset(span.end, self.lines),
        )
    }
}

pub(super) fn remap_error(
    error: crate::parser::error::ParseError,
    source_offset: u32,
    lines: &[MappedLine],
) -> crate::parser::error::ParseError {
    error.remapped(&JsxSourceMap {
        source_offset,
        lines,
    })
}

pub(super) fn remap_node_spans(node: &mut Node<'_>, source_offset: u32, lines: &[MappedLine]) {
    super::super::Parser::remap_node_spans(
        node,
        &JsxSourceMap {
            source_offset,
            lines,
        },
    );
}

fn common_line_indent(source: &str, protected: &[(usize, usize)]) -> usize {
    let bytes = source.as_bytes();
    let mut line_start = 0usize;
    let mut protected_idx = 0usize;
    let mut common = None;

    while line_start < bytes.len() {
        let (line_end, next_line) = line_bounds(bytes, line_start);
        while protected_idx < protected.len() && protected[protected_idx].1 <= line_start {
            protected_idx += 1;
        }
        let is_protected =
            protected_idx < protected.len() && protected[protected_idx].0 < line_start;
        if !is_protected
            && let Some(first_non_ws) = first_non_whitespace(bytes, line_start, line_end)
        {
            let indent = indent_width(bytes, line_start, first_non_ws);
            common = Some(common.map_or(indent, |value: usize| value.min(indent)));
            if common == Some(0) {
                break;
            }
        }
        line_start = next_line;
    }

    common.unwrap_or(0)
}

fn line_bounds(bytes: &[u8], line_start: usize) -> (usize, usize) {
    // One terminator search answers both questions: the second is the
    // width of the terminator that the first one stopped on.
    let end = line_end(bytes, line_start);
    (end, line_terminator_end(bytes, end))
}

fn first_non_whitespace(bytes: &[u8], line_start: usize, line_end: usize) -> Option<usize> {
    let mut cursor = line_start;
    while cursor < line_end && matches!(bytes[cursor], b' ' | b'\t') {
        cursor += 1;
    }
    (cursor < line_end).then_some(cursor)
}

fn indent_width(bytes: &[u8], line_start: usize, first_non_ws: usize) -> usize {
    let mut columns = 0usize;
    for &byte in &bytes[line_start..first_non_ws] {
        match byte {
            b'\t' => columns = (columns / 4 + 1) * 4,
            _ => columns += 1,
        }
    }
    columns
}

fn strip_indent_columns(bytes: &[u8], line_start: usize, line_end: usize, columns: usize) -> usize {
    let mut cursor = line_start;
    let mut column = 0usize;
    while cursor < line_end && column < columns {
        match bytes[cursor] {
            b' ' => {
                column += 1;
                cursor += 1;
            }
            b'\t' => {
                column = (column / 4 + 1) * 4;
                cursor += 1;
            }
            _ => break,
        }
    }
    cursor
}

fn boundary_offset(index: u32, lines: &[MappedLine]) -> u32 {
    let Some(first) = lines.first() else {
        return 0;
    };
    if index == 0 {
        return first.src_start;
    }
    let pos = lines.partition_point(|line| line.gen_end < index);
    if let Some(line) = lines.get(pos) {
        line.src_start + (index - line.gen_start)
    } else if let Some(last) = lines.last() {
        last.src_start + (last.gen_end - last.gen_start)
    } else {
        0
    }
}
